#!/bin/bash
set -Eeuo pipefail

# DP18 FULL RECOVERY
# SCRIPT_VERSION=1.3.0
# Recovery autonomo DD40-00000 -> DP18-xxxxx:
# - recupera matricola e prodotti dai Pardata storici
# - converte MH430/Raspberry a DP18 3.12
# - recupera la matricola MH430 via patch EEPROM nativa DP18 3.12 validata sul campo
# - ripristina firmware finale DP18 3.12
# - ricostruisce configurazione prodotti/network
# - sopravvive ai reboot Raspberry tramite servizio systemd temporaneo
# - lascia log e risultato persistenti, poi rimuove il servizio temporaneo.

SCRIPT_VERSION="1.3.0-github"
SELF="/root/DP18-FULL-RECOVERY.sh"
SERVICE="dp18-full-recovery.service"
SERVICE_FILE="/etc/systemd/system/$SERVICE"
STATE="/var/lib/dp18-full-recovery"
PAYLOADS="$STATE/payloads"
LOG="$STATE/recovery.log"
STARTED_FILE="$STATE/started_at"
ORIGINAL_INFO="$STATE/original.info"
TARGET_FILE="$STATE/target_serial"
PRODUCTS_FILE="$STATE/products.tsv"
LATEST_MH_FILE="$STATE/latest_mh430.txt"
ANALYSIS_JSON="$STATE/analysis.json"
DONE_FILE="$STATE/DONE"
FAILED_FILE="$STATE/FAILED"
CONVERSION_SENT="$STATE/conversion_312.sent"
FINAL312_SENT="$STATE/final_312.sent"
SERIAL_PATCH_SENT="$STATE/serial_patch.sent"
SERIAL_EMPTY_SENT="$STATE/serial_empty.sent"
SERIAL_ATTEMPTS="$STATE/serial_attempts"
CONFIG_DONE="$STATE/config.done"
SECRET_FILE="$STATE/sftp_password"

OFFICIAL312="$PAYLOADS/UsbUpdate_DP18_DUREX.3.12.mha"
SERIAL_TEMPLATE="$PAYLOADS/UsbUpdate_DP18_3.10_SERIAL_TEMPLATE.mha"

OFFICIAL312_SHA="cac20f0f7eb0b3ef228b41947a8bfec936554002a7a0079fbf1e3ed14a99bde2"
SERIAL_TEMPLATE_SHA="43c6c042458e9f710e1fbf7ef02d5e0087cabee37937026f83676fad406e43f7"
SERIAL_OFFSET=$((0x41138))

MODE="${1:---bootstrap}"

need() {
  command -v "$1" >/dev/null 2>&1 || {
    echo "ERRORE: comando richiesto non trovato: $1" >&2
    exit 1
  }
}

require_root() {
  [ "$(id -u)" -eq 0 ] || { echo "ERRORE: eseguire come root." >&2; exit 1; }
}

say() {
  printf '\n[%s] %s\n' "$(date '+%F %T')" "$*"
}

read_machine_name() {
  if [ -r /root/machine.name ]; then
    tr -d '\000\r\n ' < /root/machine.name
  else
    printf ''
  fi
}

read_machine_serial() {
  od -An -tu4 -N4 /root/machine.serial 2>/dev/null | tr -d ' \n'
}

serial_pad() {
  printf '%05d' "$1"
}

wait_paypoint() {
  local timeout="${1:-300}" i
  for i in $(seq 1 "$timeout"); do
    if systemctl is-active paypoint >/dev/null 2>&1; then
      return 0
    fi
    sleep 1
  done
  return 1
}

cleanup_service() {
  systemctl disable "$SERVICE" >/dev/null 2>&1 || true
  rm -f "/etc/systemd/system/multi-user.target.wants/$SERVICE" "$SERVICE_FILE"
  systemctl daemon-reload >/dev/null 2>&1 || true
}

fatal() {
  local msg="$*"
  mkdir -p "$STATE" 2>/dev/null || true
  printf '%s ERROR %s\n' "$(date -Is 2>/dev/null || date)" "$msg" >> "$LOG" 2>/dev/null || true
  printf 'RESULT=FAILED\nDATE=%s\nERROR=%s\n' "$(date -Is 2>/dev/null || date)" "$msg" > "$FAILED_FILE" 2>/dev/null || true
  local target=""
  [ -r "$TARGET_FILE" ] && target="$(tr -d '\r\n ' < "$TARGET_FILE")"
  if [ -n "$target" ]; then
    cp -f "$FAILED_FILE" "/root/DP18_RECOVERY_FAILED_${target}.txt" 2>/dev/null || true
  else
    cp -f "$FAILED_FILE" "/root/DP18_RECOVERY_FAILED.txt" 2>/dev/null || true
  fi
  cleanup_service
  rm -f "$SECRET_FILE" 2>/dev/null || true
  echo "ERRORE: $msg" >&2
  if [ "$MODE" = "--resume" ]; then
    # In servizio un errore gestito e' definitivo: exit 0 evita il Restart=on-failure.
    exit 0
  fi
  exit 1
}

capture_original_info() {
  [ -f "$ORIGINAL_INFO" ] && return 0
  {
    echo "STARTED_AT=$(date -Is 2>/dev/null || date)"
    echo "ORIGINAL_HOSTNAME=$(hostname 2>/dev/null || true)"
    echo "ORIGINAL_MACHINE_NAME=$(read_machine_name)"
    echo "ORIGINAL_MACHINE_SERIAL=$(read_machine_serial || true)"
    echo "SSH_CONNECTION=${SSH_CONNECTION:-}"
    echo "IP_LOCALI=$(hostname -I 2>/dev/null || true)"
    echo "MAC_ETH0=$(cat /sys/class/net/eth0/address 2>/dev/null || true)"
    echo "RASPBERRY_SERIAL=$(awk -F': ' '/^Serial/{print $2; exit}' /proc/cpuinfo 2>/dev/null || true)"
  } > "$ORIGINAL_INFO"
}

extract_payloads() {
  mkdir -p "$PAYLOADS"
  chmod 700 "$STATE" "$PAYLOADS" 2>/dev/null || true

  if [ ! -f "$OFFICIAL312" ] || [ "$(sha256sum "$OFFICIAL312" 2>/dev/null | awk '{print $1}')" != "$OFFICIAL312_SHA" ]; then
    say "Estraggo firmware ufficiale DP18 3.12 incorporato"
    cat <<'B64_DP18_312_GZ' | base64 -d | gzip -dc > "$OFFICIAL312.new"
