discover_history() {
  if [ -s "$TARGET_FILE" ] && [ -f "$PRODUCTS_FILE" ]; then
    local saved_pad
    saved_pad="$(tr -d '\r\n ' < "$TARGET_FILE")"
    case "$saved_pad" in
      [0-9][0-9][0-9][0-9][0-9]) ;;
      *) fatal "stato persistente target_serial non valido: $saved_pad" ;;
    esac
    [ "$saved_pad" != "00000" ] || fatal "stato persistente target_serial e' 00000"
    say "Riutilizzo storico persistente gia' recuperato: matricola $saved_pad"
    return 0
  fi

  say "Analizzo Pardata storici prima di modificare la macchina"
  local phpfile="$STATE/analyze.php"
  cat > "$phpfile" <<'PHP'
<?php
function attr_value($attrs, $name) {
    $re = '/(?:^|\s)' . preg_quote($name, '/') . '\s*=\s*(["\'])(.*?)\1/s';
    if (preg_match($re, $attrs, $m)) return html_entity_decode($m[2], ENT_QUOTES, 'UTF-8');
    return '';
}
function parse_dp18($file) {
    $txt = @file_get_contents($file);
    if ($txt === false) return false;
    if (!preg_match('/<DP18\s+([^>]*)>/s', $txt, $m)) return false;
    $root = $m[1];
    $serial = attr_value($root, 'SerialNumber');
    $ts = attr_value($root, 'TimeStamp');
    $mh = '';
    if (preg_match('/<Version\s+[^>]*descr=(["\'])(MH430:[^"\']*)\1\s*\/?>/s', $txt, $v))
        $mh = html_entity_decode($v[2], ENT_QUOTES, 'UTF-8');

    $products = array();
    if (preg_match_all('/<Product\s+([^>]*)>(.*?)<\/Product>/s', $txt, $pm, PREG_SET_ORDER)) {
        foreach ($pm as $p) {
            $a = $p[1]; $body = $p[2];
            $id = intval(attr_value($a, 'id'));
            $name = trim(attr_value($a, 'Descr'));
            $amount = intval(attr_value($a, 'Amount'));
            $count = intval(attr_value($a, 'Count'));
            $stdAmount = 0; $stdCount = 0;
            if (preg_match('/<StandardTime\s+([^>]*)\/?>/s', $body, $sm)) {
                $stdAmount = intval(attr_value($sm[1], 'Amount'));
                $stdCount = intval(attr_value($sm[1], 'Count'));
            }
            $products[] = array(
                'id'=>$id,'name'=>$name,'amount'=>$amount,'count'=>$count,
                'stdAmount'=>$stdAmount,'stdCount'=>$stdCount
            );
        }
    }
    return array('serial'=>$serial,'ts'=>$ts,'mh'=>$mh,'products'=>$products);
}

$dirs = array('/root/sent','/root/send','/root/delayedsend');
$rows = array();

foreach ($dirs as $dir) {
    if (!is_dir($dir)) continue;
    $list = glob($dir . '/DP18Data_*.xml');
    if (!$list) continue;
    foreach ($list as $file) {
        $base = basename($file);
        if (!preg_match('/^DP18Data_([0-9]{5})_([0-9]{8}_[0-9]{6})\.xml$/', $base, $m)) continue;

        $fserial = $m[1]; $fts = $m[2];
        $x = parse_dp18($file);
        if ($x === false) continue;

        $xserial = str_pad($x['serial'], 5, '0', STR_PAD_LEFT);
        $xts = preg_match('/^[0-9]{8}_[0-9]{6}$/', $x['ts']) ? $x['ts'] : $fts;
        $rows[] = array(
            'file'=>$file,'fserial'=>$fserial,'serial'=>$xserial,'ts'=>$xts,
            'mh'=>$x['mh'],'products'=>$x['products']
        );
    }
}

if (!$rows) {
    fwrite(STDERR, "Nessun DP18Data storico trovato\n");
    exit(10);
}

$candidates = array();
foreach ($rows as $r) {
    if ($r['fserial'] === '00000') continue;
    if ($r['serial'] !== $r['fserial']) continue;
    $candidates[] = $r;
}

if (!$candidates) {
    fwrite(STDERR, "Nessuna matricola storica non-zero coerente trovata\n");
    exit(11);
}

usort($candidates, function($a,$b){ return strcmp($b['ts'],$a['ts']); });
$serial = $candidates[0]['serial'];

usort($rows, function($a,$b){ return strcmp($b['ts'],$a['ts']); });

$hist = array();
foreach ($rows as $r)
    if ($r['fserial'] === $serial && $r['serial'] === $serial)
        $hist[] = $r;

usort($hist, function($a,$b){ return strcmp($b['ts'],$a['ts']); });

$latestMh = count($hist) ? $hist[0]['mh'] : '';
$products = array();

foreach ($hist as $r) {
    foreach ($r['products'] as $p) {
        $id = intval($p['id']);
        if ($id < 1 || $id > 18 || isset($products[$id])) continue;

        $name = trim($p['name']);
        $count = intval($p['count']);
        $amount = intval($p['amount']);
        if ($name === '' || $count <= 0 || $amount <= 0) continue;

        $price = null;
        $basis = 'Product';
        $sc = intval($p['stdCount']);
        $sa = intval($p['stdAmount']);

        if ($sc > 0 && $sa > 0 && ($sa % $sc) === 0) {
            $price = intval($sa / $sc);
            $basis = 'StandardTime';
        }
        if ($price === null && ($amount % $count) === 0) {
            $price = intval($amount / $count);
            $basis = 'Product';
        }
        if ($price === null || $price <= 0) continue;

        $products[$id] = array(
            'id'=>$id,'name'=>$name,'price'=>$price,'ts'=>$r['ts'],
            'file'=>$r['file'],'basis'=>$basis,'amount'=>$amount,'count'=>$count
        );
    }
}

ksort($products);

file_put_contents($argv[1], $serial . "\n");
file_put_contents($argv[2], $latestMh . "\n");

$fh = fopen($argv[3], 'w');
foreach ($products as $p) {
    fwrite($fh,
        $p['id']."\t".$p['price']."\t".
        str_replace(array("\t","\r","\n"),' ',$p['name'])."\t".
        $p['ts']."\t".$p['basis']."\t".$p['file']."\n"
    );
}
fclose($fh);

$summary = array(
    'serial'=>$serial,
    'latest_mh430'=>$latestMh,
    'products'=>$products
);
file_put_contents($argv[4], json_encode($summary, JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));
?>
PHP

  if ! php -d open_basedir= "$phpfile" "$TARGET_FILE" "$LATEST_MH_FILE" "$PRODUCTS_FILE" "$ANALYSIS_JSON"; then
    fatal "analisi Pardata fallita: impossibile ricavare una matricola DP18 storica affidabile"
  fi

  local pad
  pad="$(tr -d '\r\n ' < "$TARGET_FILE")"
  case "$pad" in
    [0-9][0-9][0-9][0-9][0-9]) ;;
    *) fatal "matricola storica non valida: $pad" ;;
  esac
  [ "$pad" != "00000" ] || fatal "la matricola storica recuperata e' 00000"

  say "Storico salvato in modo persistente"
  echo "Matricola target: $pad"
  echo "Canali recuperabili: $(wc -l < "$PRODUCTS_FILE" | tr -d ' ')"
  if [ -s "$PRODUCTS_FILE" ]; then
    printf '%-6s %-8s %-12s %s\n' CANALE PREZZO FONTE NOME
    awk -F '\t' '{printf "%-6s %-8s %-12s %s\n",$1,$2,$5,$3}' "$PRODUCTS_FILE"
  fi
}

trigger_update() {
  local src="$1" label="$2" tmp="/mhdata/UsbUpdate.mha.new.$$"
  wait_paypoint 300 || fatal "paypoint.service non e' diventato attivo"
  [ -f "$src" ] || fatal "file update non trovato: $src"

  say "MH430 update: $label"
  cp "$src" "$tmp"
  sync
  mv -f "$tmp" /mhdata/UsbUpdate.mha
  sync
  rm -f /tmp/uploads/update-ready
  touch /tmp/uploads/update-ready
  sync

  local i
  for i in $(seq 1 180); do
    if [ ! -e /tmp/uploads/update-ready ]; then
      echo "update-ready consumato dalla MH430"
      return 0
    fi
    sleep 1
  done
  fatal "timeout: MH430 non ha consumato update-ready ($label)"
}

trigger_empty_mha() {
  wait_paypoint 300 || fatal "paypoint.service non e' attivo per il reboot MH430"
  say "Forzo reboot MH430 con MHA vuoto"
  : > /mhdata/UsbUpdate.mha
  sync
  rm -f /tmp/uploads/update-ready
  touch /tmp/uploads/update-ready
  sync

  local i
  for i in $(seq 1 180); do
    if [ ! -e /tmp/uploads/update-ready ]; then
      echo "MHA vuoto consumato dalla MH430"
      return 0
    fi
    sleep 1
  done
  fatal "timeout: MHA vuoto non consumato"
}

wait_machine_dp18() {
  local seconds="${1:-900}" i name
  for i in $(seq 1 "$seconds"); do
    name="$(read_machine_name)"
    if [ "$name" = "DP18" ]; then
      return 0
    fi
    sleep 1
  done
  return 1
}

ensure_dp18_software() {
  local name
  name="$(read_machine_name)"

  case "$name" in
    DP18)
      say "Software Raspberry gia' DP18"
      return 0
      ;;
    DD40)
      ;;
    *)
      fatal "tipo macchina non supportato per recovery automatico: '${name:-vuoto}'"
      ;;
  esac

  local attempt=1
  if [ -r "$STATE/conversion_attempts" ]; then
    attempt="$(cat "$STATE/conversion_attempts" 2>/dev/null || echo 1)"
  fi

  while [ "$attempt" -le 3 ]; do
    if [ ! -e "$CONVERSION_SENT" ]; then
      echo "$attempt" > "$STATE/conversion_attempts"
      trigger_update "$OFFICIAL312" "conversione DD40 -> DP18 firmware 3.12 (tentativo $attempt)"
      date +%s > "$CONVERSION_SENT"
      say "Pacchetto DP18 3.12 consegnato. La macchina puo' riavviare il Raspberry: il recovery ripartira' automaticamente."
    else
      say "Conversione DP18 gia' richiesta in una esecuzione precedente; attendo lo stato della macchina"
    fi

    if wait_machine_dp18 900; then
      say "Raspberry ora identificato come DP18"
      return 0
    fi

    name="$(read_machine_name)"
    [ "$name" = "DP18" ] && return 0

    attempt=$((attempt+1))
    rm -f "$CONVERSION_SENT"
    echo "$attempt" > "$STATE/conversion_attempts"
    say "DP18 non ancora rilevato: preparo un nuovo tentativo"
  done

  fatal "conversione DD40 -> DP18 non completata dopo 3 tentativi"
}

make_serial_mha() {
  local target_num="$1" target_pad="$2"
  local out="$PAYLOADS/UsbUpdate_DP18_3.12_SERIAL_${target_pad}.mha"
  local hook_off=$((0x2174))
  local shell_off=$((0x4110c))
  local cfg_lit_off=$((0x41134))

  if [ -f "$out" ]; then
    local rb hk cfg
    rb="$(od -An -tu4 -N4 -j "$SERIAL_OFFSET" "$out" 2>/dev/null | tr -d ' \n')"
    hk="$(od -An -tx1 -N4 -j "$hook_off" "$out" 2>/dev/null | tr -d ' \n')"
    cfg="$(od -An -tx1 -N4 -j "$cfg_lit_off" "$out" 2>/dev/null | tr -d ' \n')"
    if [ "$rb" = "$target_num" ] && [ "$hk" = "3ef0cabf" ] && [ "$cfg" = "4c6e0010" ]; then
      echo "$out"
      return 0
    fi
  fi

  [ "$(sha256sum "$OFFICIAL312" | awk '{print $1}')" = "$OFFICIAL312_SHA" ] \
    || fatal "firmware ufficiale DP18 3.12 non integro prima del patch seriale"

  cp "$OFFICIAL312" "$out"

  local original_hook
  original_hook="$(od -An -tx1 -N4 -j "$hook_off" "$out" | tr -d ' \n')"
  [ "$original_hook" = "90b5d9b0" ] \
    || fatal "hook DP18 3.12 inatteso a 0x2174: $original_hook"

  # Hook seriale nativo DP18 3.12. La routine di salvataggio EEPROM e il punto
  # di hook sono invariati; la struttura config RAM e' 0x10006E4C sulla 3.12.
  printf '\076\360\312\277' \
    | dd of="$out" bs=1 seek="$hook_off" conv=notrunc 2>/dev/null

  printf '%s' 'kLXZsAKvCEsISpxolEII0JpgGEZO9j084EcAKAHRAkucYELyLxMYR0xuABDvvq3eAAAAAAAAAAA=' \
    | base64 -d \
    | dd of="$out" bs=1 seek="$shell_off" conv=notrunc 2>/dev/null

  local b0 b1 b2 b3
  b0=$(( target_num & 255 ))
  b1=$(( (target_num >> 8) & 255 ))
  b2=$(( (target_num >> 16) & 255 ))
  b3=$(( (target_num >> 24) & 255 ))

  printf "\\$(printf '%03o' "$b0")\\$(printf '%03o' "$b1")\\$(printf '%03o' "$b2")\\$(printf '%03o' "$b3")" \
    | dd of="$out" bs=1 seek="$SERIAL_OFFSET" conv=notrunc 2>/dev/null
  sync

  local readback hook_read cfg_read size
  readback="$(od -An -tu4 -N4 -j "$SERIAL_OFFSET" "$out" | tr -d ' \n')"
  hook_read="$(od -An -tx1 -N4 -j "$hook_off" "$out" | tr -d ' \n')"
  cfg_read="$(od -An -tx1 -N4 -j "$cfg_lit_off" "$out" | tr -d ' \n')"
  size="$(wc -c < "$out" | tr -d ' ')"

  [ "$readback" = "$target_num" ] || fatal "readback patch matricola 3.12 fallito"
  [ "$hook_read" = "3ef0cabf" ] || fatal "hook seriale 3.12 non applicato"
  [ "$cfg_read" = "4c6e0010" ] || fatal "literal config RAM 3.12 errato"
  [ "$size" = "267520" ] || fatal "dimensione MHA 3.12 patchato inattesa: $size"

  echo "$out"
}

wait_serial() {
  local wanted="$1" timeout="${2:-240}" i got
  for i in $(seq 1 "$timeout"); do
    got="$(read_machine_serial || true)"
    if [ "$got" = "$wanted" ]; then
      return 0
    fi
    sleep 1
  done
  return 1
}

recover_serial() {
  local pad num current serial_mha attempts
  pad="$(tr -d '\r\n ' < "$TARGET_FILE")"
  num=$((10#$pad))

  wait_paypoint 300 || fatal "paypoint.service non attivo prima del recupero matricola"

  current="$(read_machine_serial || true)"
  case "$current" in
    ""|*[!0-9]*) fatal "impossibile leggere /root/machine.serial" ;;
  esac

  if [ "$current" = "$num" ]; then
    say "Matricola MH430 gia' corretta: $pad"
    return 0
  fi

  [ "$current" = "0" ] || fatal "matricola corrente non-zero ($current) diversa dalla storica ($num): non sovrascrivo"

  serial_mha="$(make_serial_mha "$num" "$pad")"

  attempts=0
  [ -r "$SERIAL_ATTEMPTS" ] && attempts="$(cat "$SERIAL_ATTEMPTS" 2>/dev/null || echo 0)"

  while [ "$attempts" -lt 3 ]; do
    current="$(read_machine_serial || true)"
    [ "$current" = "$num" ] && break

    attempts=$((attempts+1))
    echo "$attempts" > "$SERIAL_ATTEMPTS"
    rm -f "$SERIAL_PATCH_SENT" "$SERIAL_EMPTY_SENT"

    trigger_update "$serial_mha" "programmatore matricola $pad su firmware DP18 3.12"
    date +%s > "$SERIAL_PATCH_SENT"
    say "Programmatore seriale consegnato; NON riavvio ancora la MH430"
    say "Attendo fino a 180 secondi che la patch dimostri di essere attiva (machine.serial=$num)"

    if ! wait_serial "$num" 180; then
      say "La matricola non e' comparsa prima del reboot: non invio MHA vuoto; riprovo il firmware patchato"
      continue
    fi

    say "Patch seriale ATTIVA: Raspberry ha ricevuto la matricola $pad dalla MH430"
    say "Attendo altri 10 secondi prima del reboot per lasciare completare il salvataggio EEPROM"
    sleep 10

    trigger_empty_mha
    date +%s > "$SERIAL_EMPTY_SENT"
    say "Reboot MH430 richiesto solo dopo conferma della matricola in RAM"

    sleep 45

    if wait_serial "$num" 180; then
      say "Matricola $pad presente anche dopo reboot MH430: persistenza EEPROM confermata"
      break
    fi

    say "Matricola persa dopo reboot MH430: riprovo il ciclo seriale"
    rm -f "$SERIAL_PATCH_SENT" "$SERIAL_EMPTY_SENT"
  done

  current="$(read_machine_serial || true)"
  [ "$current" = "$num" ] || fatal "recupero matricola $pad fallito dopo 3 tentativi"

  say "Matricola recuperata e confermata dalla MH430: $pad"
}
ensure_final_312() {
  if [ -e "$FINAL312_SENT" ]; then
    say "Firmware finale DP18 3.12 gia' richiesto; non ripeto il flash"
    wait_paypoint 300 || fatal "paypoint.service non attivo dopo firmware finale"
    return 0
  fi

  trigger_update "$OFFICIAL312" "ripristino firmware finale ufficiale DP18 3.12"
  date +%s > "$FINAL312_SENT"
  say "Firmware finale DP18 3.12 consegnato. Eventuali reboot Raspberry sono gestiti automaticamente."
  sleep 30
  wait_paypoint 300 || fatal "paypoint.service non tornato attivo dopo firmware finale"
}

wait_marker_gone() {
  local marker="$1" seconds="${2:-120}" i
  for i in $(seq 1 "$seconds"); do
    [ ! -e "$marker" ] && return 0
    sleep 1
  done
  return 1
}

request_config_backup() {
  local dest="$1"
  local config="/mhdata/DP18Config.txt"
  local config_needed="/tmp/uploads/config-needed"
  local config_file_ready="/tmp/config-file-ready"
  local i

  wait_paypoint 300 || fatal "paypoint.service non attivo per richiesta configurazione"

  # Se una richiesta precedente e' rimasta pendente per un reboot, prima lasciamo
  # alla MH430 la possibilita' di consumarla.
  if [ -e "$config_needed" ]; then
    wait_marker_gone "$config_needed" 60 || rm -f "$config_needed"
  fi

  rm -f "$config_file_ready"
  touch "$config_needed"
  sync

  for i in $(seq 1 180); do
    if [ ! -e "$config_needed" ] && [ -e "$config_file_ready" ]; then
      sleep 2
      sync
      if [ -f "$config" ] \
         && grep -q '^;;BEGIN' "$config" \
         && grep -q '^\[Products\]' "$config" \
         && grep -q '^\[Network\]' "$config" \
         && [ "$(wc -c < "$config" | tr -d ' ')" -ge 200 ]; then
        cp -a "$config" "$dest"
        rm -f "$config_file_ready"
        return 0
      fi
    fi
    sleep 1
  done

  fatal "timeout: la MH430 non ha restituito un DP18Config.txt valido"
}

apply_configuration() {
  local sftp_password
  [ -r "$SECRET_FILE" ] || fatal "password SFTP recovery non disponibile"
  sftp_password="$(cat "$SECRET_FILE")"
  [ -n "$sftp_password" ] || fatal "password SFTP recovery vuota"
  [ -e "$CONFIG_DONE" ] && { say "Configurazione gia' verificata in una esecuzione precedente"; return 0; }

  local work="$STATE/config-work"
  local config="/mhdata/DP18Config.txt"
  local config_ready="/tmp/uploads/config-ready"
  local products_needed="/tmp/uploads/products-needed"
  local basecfg="$work/DP18Config.before.txt"
  local recoveredcfg="$work/DP18Config.recovered.txt"
  local verifycfg="$work/DP18Config.verify.txt"
  local recovered_ids="$work/recovered.ids"

  mkdir -p "$work"

  say "Richiedo alla MH430 il backup della configurazione corrente"
  request_config_backup "$basecfg"

  php -d open_basedir= -r '
function set_section_key($s,$section,$key,$value){
  $sp="/(?ms)^\\[".preg_quote($section,"/")."\\]\\R.*?(?=^\\[|\\z)/";
  if(!preg_match($sp,$s,$m,PREG_OFFSET_CAPTURE)){
    fwrite(STDERR,"Sezione mancante: [".$section."]\\n"); exit(20);
  }
  $block=$m[0][0]; $off=$m[0][1];
  $kp="/(?m)^".preg_quote($key,"/")."=.*$/";
  if(preg_match($kp,$block)){
    $block=preg_replace($kp,$key."=".$value,$block,1,$n);
    if($n!==1){fwrite(STDERR,"Impossibile aggiornare chiave: ".$key."\\n");exit(21);}
  } else {
    $trimmed=rtrim($block,"\r\n");
    $block=$trimmed."\n".$key."=".$value."\n\n";
  }
  return substr_replace($s,$block,$off,strlen($m[0][0]));
}

$base=$argv[1]; $tsv=$argv[2]; $out=$argv[3]; $sftpPassword=$argv[4];
$s=file_get_contents($base); if($s===false) exit(2);
$rows=file($tsv, FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES);
$rec=array();

foreach($rows as $line){
  $p=explode("\t",$line,6); if(count($p)<3) continue;
  $id=intval($p[0]); $price=intval($p[1]); $name=trim($p[2]);
  if($id<1 || $id>18 || $price<=0 || $name==="") continue;
  $name=str_replace(array("\r","\n")," ",$name);
  if(strpos($name,"=")!==false){fwrite(STDERR,"Nome prodotto con = non supportato: ".$name."\n");exit(3);}
  $rec[$id]=array("name"=>$name,"price"=>$price);
}

for($id=1;$id<=18;$id++){
  $idx=$id-1;
  $kn="product-name_".$idx;
  $kp="product-price-normal_".$idx."_0_0";
  $kf="product-flag_".$idx;

  if(isset($rec[$id])){
    $s=set_section_key($s,"Products",$kn,$rec[$id]["name"]);
    $s=set_section_key($s,"Products",$kp,strval($rec[$id]["price"]));
    $s=set_section_key($s,"Products",$kf,"3");
  } else {
    $s=set_section_key($s,"Products",$kn,"Nome Vuoto!!!");
    $s=set_section_key($s,"Products",$kf,"0");
  }
}

$network=array(
  "server-protocol"=>"sftp",
  "server-port"=>"22",
  "server-address"=>"vnd.microhard.it",
  "server-username"=>"uploads",
  "server-password"=>$sftpPassword,
  "alarm-email"=>"",
  "transmission-interval-hours"=>"24",
  "transmission-time-year"=>"26",
  "transmission-time-month"=>"9",
  "transmission-time-day"=>"5",
  "transmission-time-hh"=>"1",
  "transmission-time-mm"=>"0"
);
foreach($network as $k=>$v) $s=set_section_key($s,"Network",$k,$v);

if(file_put_contents($out,$s)===false) exit(6);
' "$basecfg" "$PRODUCTS_FILE" "$recoveredcfg" "$sftp_password" || fatal "ricostruzione DP18Config fallita"

  grep -q '^;;BEGIN' "$recoveredcfg" || fatal "config ricostruita non valida"
  grep -q '^\[Products\]' "$recoveredcfg" || fatal "config ricostruita senza [Products]"
  grep -q '^\[Network\]' "$recoveredcfg" || fatal "config ricostruita senza [Network]"

  cut -f1 "$PRODUCTS_FILE" > "$recovered_ids"

  local recovered_count disabled_count
  recovered_count="$(wc -l < "$recovered_ids" | tr -d ' ')"
  disabled_count=$((18-recovered_count))

  say "Configurazione ricostruita: $recovered_count canali recuperati, $disabled_count non vendibili"

  if [ -e "$config_ready" ]; then
    wait_marker_gone "$config_ready" 60 || rm -f "$config_ready"
  fi
  if [ -e "$products_needed" ]; then
    wait_marker_gone "$products_needed" 60 || rm -f "$products_needed"
  fi

  local tmp="/mhdata/DP18Config.txt.new.$$"
  cp "$recoveredcfg" "$tmp"
  sync
  mv -f "$tmp" "$config"
  sync

  touch "$config_ready"
  touch "$products_needed"
  sync

  wait_marker_gone "$config_ready" 180 || fatal "timeout: config-ready non consumato"
  wait_marker_gone "$products_needed" 180 || fatal "timeout: products-needed non consumato"

  say "Configurazione acquisita dalla MH430; eseguo rilettura reale di verifica"
  request_config_backup "$verifycfg"

  local verified=1 id idx line rid price name ts basis src expected
  for id in $(seq 1 18); do
    idx=$((id-1))
    if grep -qx "$id" "$recovered_ids"; then
      line="$(awk -F '\t' -v want="$id" '$1==want{print; exit}' "$PRODUCTS_FILE")"
      IFS=$'\t' read -r rid price name ts basis src <<< "$line"
      grep -Fqx "product-name_${idx}=${name}" "$verifycfg" || { echo "Verifica fallita nome canale $id"; verified=0; }
      grep -Fqx "product-price-normal_${idx}_0_0=${price}" "$verifycfg" || { echo "Verifica fallita prezzo canale $id"; verified=0; }
      grep -Fqx "product-flag_${idx}=3" "$verifycfg" || { echo "Verifica fallita flag vendibile canale $id"; verified=0; }
    else
      grep -Fqx "product-name_${idx}=Nome Vuoto!!!" "$verifycfg" || { echo "Verifica fallita nome vuoto canale $id"; verified=0; }
      grep -Fqx "product-flag_${idx}=0" "$verifycfg" || { echo "Verifica fallita flag NON vendibile canale $id"; verified=0; }
    fi
  done

  while IFS= read -r expected; do
    [ -n "$expected" ] || continue
    grep -Fqx "$expected" "$verifycfg" || { echo "Verifica fallita Network: $expected"; verified=0; }
  done <<'NETWORK_EXPECTED'
server-protocol=sftp
server-port=22
server-address=vnd.microhard.it
server-username=uploads
alarm-email=
transmission-interval-hours=24
transmission-time-year=26
transmission-time-month=9
transmission-time-day=5
transmission-time-hh=1
transmission-time-mm=0
NETWORK_EXPECTED

  grep -Fqx "server-password=${sftp_password}" "$verifycfg" || { echo "Verifica fallita Network: server-password"; verified=0; }

  [ "$verified" -eq 1 ] || fatal "config applicata ma rilettura MH430 non coincide"

  {
    echo "RECOVERED_COUNT=$recovered_count"
    echo "DISABLED_COUNT=$disabled_count"
  } > "$CONFIG_DONE"

  say "Configurazione prodotti/network verificata"
}

wait_hostname_target() {
  local pad="$1" timeout="${2:-240}" i hn
  for i in $(seq 1 "$timeout"); do
    hn="$(hostname 2>/dev/null || true)"
    case "$hn" in
      "DP18-$pad"|*"$pad") return 0 ;;
    esac
    sleep 1
  done
  return 1
}

finish_success() {
  local pad num current recovered disabled oldhost
  pad="$(tr -d '\r\n ' < "$TARGET_FILE")"
  num=$((10#$pad))
  current="$(read_machine_serial || true)"

  [ "$(read_machine_name)" = "DP18" ] || fatal "verifica finale: machine.name non e' DP18"
  [ "$current" = "$num" ] || fatal "verifica finale: seriale corrente $current diverso da $num"
  [ -e "$CONFIG_DONE" ] || fatal "verifica finale: configurazione non marcata come completata"
  wait_hostname_target "$pad" 240 || fatal "verifica finale: hostname non e' diventato DP18-$pad"

  recovered="$(awk -F= '$1=="RECOVERED_COUNT"{print $2}' "$CONFIG_DONE")"
  disabled="$(awk -F= '$1=="DISABLED_COUNT"{print $2}' "$CONFIG_DONE")"
  oldhost="$(awk -F= '$1=="ORIGINAL_HOSTNAME"{sub(/^[^=]*=/,""); print}' "$ORIGINAL_INFO" | head -1)"

  {
    echo "RESULT=OK"
    echo "SCRIPT_VERSION=$SCRIPT_VERSION"
    echo "STARTED_AT=$(awk -F= '$1=="STARTED_AT"{sub(/^[^=]*=/,""); print}' "$ORIGINAL_INFO" | head -1)"
    echo "COMPLETED_AT=$(date -Is 2>/dev/null || date)"
    echo "OLD_HOSTNAME=$oldhost"
    echo "RECOVERED_SERIAL=$pad"
    echo "NEW_HOSTNAME=$(hostname)"
    echo "MACHINE_NAME=$(read_machine_name)"
    echo "MACHINE_SERIAL=$current"
    echo "CHANNELS_RECOVERED=$recovered"
    echo "CHANNELS_DISABLED=$disabled"
    echo "FIRMWARE_TARGET=MH430_DP18_3.12"
    echo "MHA_SHA256=$OFFICIAL312_SHA"
    echo "MAC_ETH0=$(cat /sys/class/net/eth0/address 2>/dev/null || true)"
    echo "RASPBERRY_SERIAL=$(awk -F': ' '/^Serial/{print $2; exit}' /proc/cpuinfo 2>/dev/null || true)"
    echo "LOG=$LOG"
  } > "$DONE_FILE"

  cp -f "$DONE_FILE" "/root/DP18_RECOVERY_OK_${pad}.txt"
  printf '%s %s %s recovered=%s disabled=%s\n' \
    "$(date -Is 2>/dev/null || date)" "$pad" "$(hostname)" "$recovered" "$disabled" \
    >> /root/DP18_RECOVERY_HISTORY.log

  cleanup_service
  rm -f "$SECRET_FILE" 2>/dev/null || true

  say "==============================================="
  say "DP18 FULL RECOVERY COMPLETATO"
  echo "Matricola : $pad"
  echo "Hostname  : $(hostname)"
  echo "Canali    : $recovered recuperati, $disabled non vendibili"
  echo "Risultato : /root/DP18_RECOVERY_OK_${pad}.txt"
  echo "Log       : $LOG"
  say "Servizio temporaneo rimosso: recovery terminato"
}

resume_main() {
  mkdir -p "$STATE" "$PAYLOADS"
  chmod 700 "$STATE" "$PAYLOADS" 2>/dev/null || true
  touch "$STARTED_FILE"

  # Log persistente + journal/systemd.
  exec > >(tee -a "$LOG") 2>&1

  say "DP18 FULL RECOVERY v$SCRIPT_VERSION - resume"
  echo "Hostname attuale : $(hostname)"
  echo "machine.name     : $(read_machine_name)"
  echo "machine.serial   : $(read_machine_serial || true)"

  discover_history
  extract_payloads

  local pad num current
  pad="$(tr -d '\r\n ' < "$TARGET_FILE")"
  num=$((10#$pad))

  # Se in qualunque fase la macchina e' gia' completamente recuperata, il flusso
  # resta idempotente e procede solo con gli step ancora mancanti.
  ensure_dp18_software

  wait_paypoint 300 || fatal "paypoint.service non attivo dopo conversione DP18"

  recover_serial

  # Appena il seriale e' corretto il conflitto VPN DD40-00000/DP18-00000 e'
  # sostanzialmente risolto; da qui in poi il recovery puo' continuare anche
  # attraverso ulteriori reboot.
  current="$(read_machine_serial || true)"
  [ "$current" = "$num" ] || fatal "seriale non corretto dopo recover_serial"

  ensure_final_312

  # Dopo un eventuale reboot causato dal firmware finale il servizio riparte e
  # arriva nuovamente qui. Attendiamo ambiente DP18/paypoint stabile.
  wait_machine_dp18 600 || fatal "machine.name non e' DP18 dopo firmware finale"
  wait_paypoint 300 || fatal "paypoint.service non attivo dopo firmware finale"
  sleep 10

  apply_configuration
  finish_success
}

bootstrap() {
  require_root
  for c in bash php base64 gzip od dd awk sed grep sort cp mv sync sha256sum seq tee wc tr date hostname sleep systemctl stat find head cat mkdir rm chmod; do
    need "$c"
  done

  mkdir -p "$STATE" "$PAYLOADS"
  chmod 700 "$STATE" "$PAYLOADS"

  # Idempotenza: una DP18 gia' dotata di seriale non-zero non viene mai
  # riportata dentro la procedura di discovery/flash per errore.
  local boot_name boot_serial boot_pad saved_pad
  boot_name="$(read_machine_name)"
  boot_serial="$(read_machine_serial || true)"
  if [ "$boot_name" = "DP18" ]; then
    case "$boot_serial" in
      ''|*[!0-9]*) ;;
      0) ;;
      *)
        boot_pad="$(printf '%05d' "$boot_serial")"
        saved_pad=""
        [ -r "$TARGET_FILE" ] && saved_pad="$(tr -d '\r\n ' < "$TARGET_FILE")"
        if [ -z "$saved_pad" ] || [ "$saved_pad" = "$boot_pad" ]; then
          say "Macchina gia' DP18 con matricola non-zero: $boot_pad"
          if [ -f "/root/DP18_RECOVERY_OK_${boot_pad}.txt" ] || [ -e "$CONFIG_DONE" ]; then
            say "Recovery gia' completata: non eseguo nuovamente analisi Pardata o flash"
          else
            say "Nessuno stato completo disponibile: per sicurezza non sovrascrivo una DP18 gia' matricolata"
          fi
          cleanup_service
          rm -f "$SECRET_FILE" 2>/dev/null || true
          return 0
        fi
        fatal "DP18 gia' matricolata $boot_pad ma stato persistente indica $saved_pad: non procedo"
        ;;
    esac
  fi

  rm -f "$FAILED_FILE"
  rm -f "$SERIAL_PATCH_SENT" "$SERIAL_EMPTY_SENT" "$SERIAL_ATTEMPTS" "$FINAL312_SENT" "$CONFIG_DONE"

  if [ -n "${DP18_SFTP_PASSWORD:-}" ]; then
    umask 077
    printf "%s" "$DP18_SFTP_PASSWORD" > "$SECRET_FILE"
    chmod 600 "$SECRET_FILE"
  fi
  [ -s "$SECRET_FILE" ] || fatal "DP18_SFTP_PASSWORD non fornita al bootstrap"
  capture_original_info

  # Verifica subito storico e payload: non tocchiamo MH430 se qualcosa non torna.
  discover_history
  extract_payloads

  local pad name
  pad="$(tr -d '\r\n ' < "$TARGET_FILE")"
  name="$(read_machine_name)"

  case "$name" in
    DD40|DP18) ;;
    *) fatal "machine.name non supportato: '${name:-vuoto}'" ;;
  esac

  cat > "$SERVICE_FILE" <<EOF
[Unit]
Description=DP18 Full Automatic Recovery
After=local-fs.target paypoint.service

[Service]
Type=simple
ExecStart=/bin/bash $SELF --resume
Restart=on-failure
RestartSec=20

[Install]
WantedBy=multi-user.target
EOF

  systemctl daemon-reload
  systemctl enable "$SERVICE" >/dev/null

  say "Bootstrap installato"
  echo "Target matricola : $pad"
  echo "Tipo attuale     : $name"
  echo "Servizio         : $SERVICE"
  echo "Log persistente  : $LOG"
  echo
  echo "Da questo momento puoi perdere la sessione SSH/VPN: il recovery prosegue da solo."
  echo "Anche un reboot del Raspberry e' gestito automaticamente."

  systemctl restart "$SERVICE"
}

status_mode() {
  echo "=== DP18 FULL RECOVERY STATUS ==="
  if [ -r "$TARGET_FILE" ]; then echo "Target: $(cat "$TARGET_FILE")"; else echo "Target: non ancora determinato"; fi
  echo "machine.name  : $(read_machine_name)"
  echo "machine.serial: $(read_machine_serial || true)"
  echo "hostname      : $(hostname 2>/dev/null || true)"
  echo "service       : $(systemctl is-active "$SERVICE" 2>/dev/null || true)"
  [ -f "$DONE_FILE" ] && { echo "--- DONE ---"; cat "$DONE_FILE"; }
  [ -f "$FAILED_FILE" ] && { echo "--- FAILED ---"; cat "$FAILED_FILE"; }
  [ -f "$LOG" ] && { echo "--- ULTIME 40 RIGHE LOG ---"; tail -40 "$LOG"; }
}

