B64_B

  [ "$(sha256sum "$tmp/a.mha" | awk '{print $1}')" = "$OFFICIAL312_SHA" ] || { echo "SELFTEST FAIL official312"; exit 1; }
  [ "$(sha256sum "$tmp/b.mha" | awk '{print $1}')" = "$SERIAL_TEMPLATE_SHA" ] || { echo "SELFTEST FAIL template"; exit 1; }
  [ "$(od -An -tx1 -N4 -j "$SERIAL_OFFSET" "$tmp/b.mha" | tr -d ' \n')" = "efbeadde" ] || { echo "SELFTEST FAIL placeholder"; exit 1; }

  echo "SELFTEST OK"
  echo "DP18 3.12 SHA256    : $OFFICIAL312_SHA"
  echo "Serial template SHA : $SERIAL_TEMPLATE_SHA"
}

case "$MODE" in
  --bootstrap)
    bootstrap
    ;;
  --resume)
    require_root
    for c in bash php base64 gzip od dd awk sed grep sort cp mv sync sha256sum seq tee wc tr date hostname sleep systemctl stat find head cat mkdir rm chmod; do
      need "$c"
    done
    resume_main
    ;;
  --status)
    status_mode
    ;;
  --selftest)
    selftest
    ;;
  *)
    echo "Uso: $0 [--bootstrap|--resume|--status|--selftest]" >&2
    exit 2
    ;;
esac

# END_DP18_FULL_RECOVERY_v1
